    .site-header{position:sticky;top:0;z-index:50;padding:12px 0;background:linear-gradient(180deg,rgba(240,236,223,.96),rgba(240,236,223,.78),transparent)}.nav{display:flex;align-items:center;gap:16px;padding:10px 12px 10px 16px;border:1px solid rgba(255,255,255,.12);border-radius:22px;background:rgba(6,26,21,.89);box-shadow:0 24px 70px -46px rgba(0,0,0,.9);backdrop-filter:blur(22px) saturate(130%);color:#fff}.brand{display:flex;align-items:center;gap:11px;min-width:0}.brand-mark{display:grid;place-items:center;width:42px;height:42px;flex:0 0 auto;border:1px solid rgba(223,252,98,.42);border-radius:15px;background:rgba(223,252,98,.08);color:var(--acid)}.brand-copy{min-width:0;line-height:1}.brand-copy strong{display:block;font-family:"Fraunces",serif;font-size:18px;font-weight:600;letter-spacing:-.02em}.brand-copy span{display:block;margin-top:5px;color:rgba(255,255,255,.5);font-size:10px;font-weight:700;letter-spacing:.18em;text-transform:uppercase;white-space:nowrap}.main-nav{display:flex;align-items:center;gap:6px;margin-left:auto}.main-nav a{padding:10px 12px;border-radius:12px;color:rgba(255,255,255,.68);font-size:13px;font-weight:600}.main-nav a:hover{background:rgba(255,255,255,.07);color:#fff}.nav-actions{display:flex;align-items:center;gap:8px}.nav-icon,.menu-btn{display:grid;place-items:center;width:40px;height:40px;border:0;border-radius:13px;background:rgba(255,255,255,.07);color:#fff;cursor:pointer}.ticket-cta{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:0 16px;border-radius:13px;background:var(--acid);color:var(--pine-950);font-size:13px;font-weight:800;white-space:nowrap}.menu-btn{display:none}
