ight:188px}.saved-mini{position:absolute;width:220px;padding:13px;border:1px solid rgba(255,255,255,.15);border-radius:20px;background:rgba(6,26,21,.74);box-shadow:0 24px 48px -28px rgba(0,0,0,.8);backdrop-filter:blur(18px)}.saved-mini:nth-child(1){right:10px;bottom:4px;transform:rotate(4deg)}.saved-mini:nth-child(2){left:4px;top:22px;transform:rotate(-7deg)}.saved-mini:nth-child(3){right:28px;top:0;transform:rotate(1deg)}.saved-mini span{display:block;color:var(--acid);font-size:9px;font-weight:800;letter-spacing:.13em;text-transform:uppercase}.saved-mini strong{display:block;margin-top:6px;font-family:"Fraunces",serif;font-size:17px}.saved-mini small{display:block;margin-top:4px;color:rgba(255,255,255,.5);font-size:9px}
    .toolbar{position:sticky;top:88px;z-index:18;display:flex;align-items:center;justify-content:space-between;gap:12px;margin:16px 0;padding:9px;border:1px solid var(--line);border-radius:20px;background:rgba(240,236,223,.9);backdrop-filter:blur(18px);box-shadow:var(--card-shadow)}.tabs{display:flex;gap:6px;min-width:0;overflow-x:auto;scrollbar-width:none}.tabs::-webkit-scrollbar{display:none}.tab{flex:0 0 auto;min-height:42px;padding:0 14px;border:0;border-radius:13px;background:transparent;color:var(--muted);cursor:pointer;font-size:12px;font-weight:800;white-space:nowrap}.tab.active{background:var(--pine-900);color:#fff}.toolbar-actions{display:flex;gap:8px;flex:0 0 auto}.search{position:relative}.search input{width:220px;height:42px;padding:0 14px 0 39px;border:1px solid var(--line);border-radius:13px;background:var(--cream);outline:none;color:var(--ink);font-size:12px}.search svg{position:absolute;left:13px;top:12px;width:18px;color:rgba(22,35,30,.42)}.icon-btn{display:grid;place-items:center;width:42px;height:42px;border:1px solid var(--line);border-radius:13px;background:var(--cream);color:var(--pine-900);cursor:pointer}
    .main-grid{display:grid;grid-template-columns:minmax(0,1fr) 315px;gap:16px}.stack{display:grid;gap:16px}.feature{overflow:hidden;display:grid;grid-template-columns:minmax(0,1.05fr) minmax(280px,.95fr);min-height:360px;border-radius:30px;background:var(--cream);box-shadow:var(--card-shadow);border:1px solid var(--line)}.feature-media{position:relative;min-height:360px}.feature-media img{height:100%;object-fit:cover}.feature-media:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 40%,rgba(6,26,21,.72))}.feature-badge{position:absolute;left:18px;top:18px;z-index:2;padding:8px 10px;border-radius:999px;background:var(--acid);color:var(--pine-950);font-size:9px;font-weight:900;letter-spacing:.12em;text-transform:uppercase}.feature-note{position:absolute;left:18px;right:18px;bottom:17px;z-index:2;display:flex;align-items:end;justify-content:space-between;gap:12px;color:#fff}.feature-note strong{display:block;font-family:"Fraunces",serif;font-size:25px}.feature-note span{display:block;margin-top:4px;color:rgba(255,255,255,.62);font-size:10px}.feature-note b{padding:7px 9px;border-radius:10px;background:rgba(242,123,74,.95);font-size:10px;white-space:nowrap}.feature-copy{display:flex;flex-direction:column;justify-content:center;padding:30px}.kicker{margin:0 0 8px;color:var(--pine-700);font-size:9px;font-weight:900;letter-spacing:.15em;text-transform:uppercase}.feature h2,.section-head h2{margin:0;font-family:"Fraunces",serif;font-weight:600;letter-spacing:-.035em}.feature h2{font-size:34px}.feature-copy>p{margin:12px 0 20px;color:var(--muted);font-size:13px;line-height:1.65}.facts{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.fact{padding:12px;border-radius:15px;background:var(--oat)}.fact strong{display:block;font-size:12px}.fact span{display:block;margin-top:3px;color:var(--muted);font-size:9px}.feature-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:20px}.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px;padding:0 16px;border:0;border-radius:14px;cursor:pointer;font-size:12px;font-weight:800;transition:.2s ease}.btn:hover{transform:translateY(-2px)}.btn-primary{background:var(--acid);color:var(--pine-950)}.btn-dark{background:var(--pine-900);color:#fff}.btn-soft{border:1px solid var(--line);background:var(--cream);color:var(--pine-900)}
    .section{padding:22px;border:1px solid var(--line);border-radius:28px;background:rgba(255,253,246,.76);box-shadow:var(--card-shadow)}.section-head{display:flex;align-items:end;justify-content:space-between;gap:14px;margin-bottom:16px}.section-head h2{font-size:29px}.section-head p{max-width:520px;margin:6px 0 0;color:var(--muted);font-size:12px;line-height:1.55}.section-head button{flex:0 0 auto}.adventure-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.adventure-card{position:relative;overflow:hidden;border:1px solid var(--line);border-radius:23px;background:var(--cream);transition:.25s ease}.adventure-card:hover{transform:translateY(-4px);box-shadow:0 22px 42px -34px rgba(6,26,21,.7)}.card-media{position:relative;height:210px;overflow:hidden}.card-media img{height:100%;object-fit:cover;transition:.45s ease}.adventure-card:hover img{transform:scale(1.035)}.card-media:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 45%,rgba(6,26,21,.64))}.heart{position:absolute;right:12px;top:12px;z-index:3;display:grid;place-items:center;width:38px;height:38px;border:0;border-radius:13px;background:rgba(6,26,21,.74);color:var(--acid);cursor:pointer;backdrop-filter:blur(12px)}.heart.removed{color:#fff}.card-tags{position:absolute;left:12px;bottom:12px;z-index:3;display:flex;gap:6px;flex-wrap:wrap}.tag{padding:6px 8px;border-radius:999px;background:rgba(6,26,21,.75);color:#fff;font-size:8px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;backdrop-filter:blur(10px)}.tag.alert{background:var(--ember)}.card-body{padding:17px}.card-top{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.card-body h3{margin:0;font-family:"Fraunces",serif;font-size:22px;font-weight:600}.card-body p{margin:7px 0 14px;color:var(--muted);font-size:11px;line-height:1.55}.card-price{color:var(--pine-900);font-family:"Fraunces",serif;font-size:17px;white-space:nowrap}.card-meta{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin:12px 0}.meta-item{padding:9px;border-radius:12px;background:var(--oat)}.meta-item strong{display:block;font-size:10px}.meta-item span{display:block;margin-top:2px;color:var(--muted);font-size:8px}.card-actions{display:grid;grid-template-columns:1fr auto auto;gap:7px}.card-actions .btn{min-height:40px;padding:0 12px}.small-icon{display:grid;place-items:center;width:40px;height:40px;border:1px solid var(--line);border-radius:12px;background:var(--cream);cursor:pointer;color:var(--pine-900)}.select-card{position:absolute;left:12px;top:12px;z-index:3}.select-card input{position:absolute;opacity:0;pointer-events:none}.select-card label{display:grid;place-items:center;width:38px;height:38px;border:1px solid rgba(255,255,255,.2);border-radius:13px;background:rgba(6,26,21,.66);color:#fff;cursor:pointer;backdrop-filter:blur(10px)}.select-card input:checked+label{background:var(--acid);color:var(--pine-950);border-color:var(--acid)}
    .aside-card{padding:20px;border:1px solid var(--line);border-radius:25px;background:var(--cream);box-shadow:var(--card-shadow)}.aside-card.dark{background:var(--pine-900);color:#fff}.aside-card h3{margin:0;font-family:"Fraunces",serif;font-size:23px;font-weight:600}.aside-card>p{margin:8px 0 16px;color:var(--muted);font-size:11px;line-height:1.55}.aside-card.dark>p{color:rgba(255,255,255,.56)}.collection-list{display:grid;gap:8px}.collection{display:flex;align-items:center;gap:11px;padding:10px;border:1px solid var(--line);border-radius:15px;background:var(--oat);cursor:pointer;text-align:left}.collection.active{background:var(--pine-900);color:#fff}.collection-thumb{width:48px;height:48px;flex:0 0 auto;border-radius:12px;object-fit:cover}.collection-copy{min-width:0;flex:1}.collection-copy strong{display:block;font-size:11px}.collection-copy span{display:block;margin-top:3px;color:var(--muted);font-size:9px}.collection.active .collection-copy span{color:rgba(255,255,255,.52)}.collection b{font-size:10px}.create-collection{width:100%;margin-top:10px}.watch-item{display:flex;gap:11px;padding:11px 0;border-bottom:1px solid rgba(255,255,255,.1)}.watch-item:last-child{border-bottom:0}.watch-icon{display:grid;place-items:center;width:38px;height:38px;flex:0 0 auto;border-radius:13px;background:rgba(223,252,98,.1);color:var(--acid)}.watch-copy strong{display:block;font-size:11px}.watch-copy span{display:block;margin-top:3px;color:rgba(255,255,255,.52);font-size:9px;line-height:1.45}.watch-copy b{color:var(--acid)}.suggestion{overflow:hidden;position:relative;min-height:260px;padding:20px;border-radius:25px;background:var(--pine-900);color:#fff}.suggestion:before{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(6,26,21,.12),rgba(6,26,21,.92)),url("https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=900&q=84") center/cover}.suggestion>*{position:relative;z-index:2}.suggestion small{color:var(--acid);font-size:9px;font-weight:900;letter-spacing:.14em;text-transform:uppercase}.suggestion h3{max-width:220px;margin:85px 0 8px;font-family:"Fraunces",serif;font-size:27px}.suggestion p{margin:0 0 15px;color:rgba(255,255,255,.6);font-size:10px;line-height:1.5}
    .empty{display:none;padding:54px 20px;text-align:center}.empty.visible{display:block}.empty-icon{display:grid;place-items:center;width:66px;height:66px;margin:0 auto 14px;border-radius:22px;background:var(--oat);color:var(--pine-900)}.empty h3{margin:0;font-family:"Fraunces",serif;font-size:27px}.empty p{max-width:420px;margin:8px auto 18px;color:var(--muted);font-size:12px;line-height:1.6}
    .plan-bar{position:fixed;left:50%;bottom:24px;z-index:40;display:flex;align-items:center;gap:14px;width:min(720px,calc(100% - 32px));padding:11px 12px 11px 17px;border:1px solid rgba(255,255,255,.16);border-radius:20px;background:rgba(6,26,21,.92);box-shadow:0 30px 80px -38px rgba(0,0,0,.88);color:#fff;backdrop-filter:blur(22px);transform:translate(-50%,130%);transition:.28s ease}.plan-bar.visible{transform:translate(-50%,0)}.plan-copy{min-width:0;flex:1}.plan-copy strong{display:block;font-size:12px}.plan-copy span{display:block;margin-top:3px;color:rgba(255,255,255,.5);font-size:9px}.plan-chips{display:flex;gap:6px}.plan-chip{width:34px;height:34px;border:2px solid var(--pine-900);border-radius:11px;object-fit:cover}.plan-bar .btn{flex:0 0 auto}
    .modal{position:fixed;inset:0;z-index:90;display:grid;place-items:center;padding:18px;background:rgba(6,26,21,.72);opacity:0;pointer-events:none;transition:.2s ease}.modal.open{opacity:1;pointer-events:auto}.modal-card{position:relative;width:min(620px,100%);max-height:min(86vh,760px);overflow:auto;padding:25px;border:1px solid rgba(255,255,255,.16);border-radius:28px;background:var(--cream);box-shadow:0 44px 100px -38px rgba(0,0,0,.85);transform:translateY(18px) scale(.98);transition:.25s ease}.modal.open .modal-card{transform:none}.modal-close{position:absolute;right:15px;top:15px;display:grid;place-items:center;width:38px;height:38px;border:0;border-radius:13px;background:var(--oat);cursor:pointer}.modal-kicker{display:block;color:var(--pine-700);font-size:9px;font-weight:900;letter-spacing:.14em;text-transform:uppercase}.modal h3{margin:9px 40px 8px 0;font-family:"Fraunces",serif;font-size:31px}.modal p{margin:0;color:var(--muted);font-size:12px;line-height:1.6}.field{display:grid;gap:7px;margin-top:16px}.field label{font-size:10px;font-weight:800}.control{width:100%;min-height:46px;padding:0 13px;border:1px solid var(--line);border-radius:13px;background:var(--cream);outline:none}.itinerary{display:grid;gap:9px;margin-top:18px}.itinerary-item{display:grid;grid-template-columns:54px 1fr;gap:11px;padding:12px;border-radius:16px;background:var(--oat)}.itinerary-item time{color:var(--pine-700);font-size:10px;font-weight:900}.itinerary-item strong{display:block;font-size:11px}.itinerary-item span{display:block;margin-top:3px;color:var(--muted);font-size:9px}.modal-actions{display:flex;gap:8px;margin-top:18px}.toast{position:fixed;right:18px;bottom:22px;z-index:120;max-width:min(360px,calc(100% - 36px));padding:13px 16px;border-radius:15px;background:var(--pine-950);color:#fff;box-shadow:0 24px 54px -28px rgba(0,0,0,.8);font-size:11px;transform:translateY(130%);transition:.25s ease}.toast.show{transform:translateY(0)}
    .mobile-nav{display:none}.mobile-menu{position:fixed;inset:0;z-index:80;padding:16px;background:var(--pine-950);color:#fff;transform:translateX(100%);transition:.3s ease}.mobile-menu.open{transform:none}.mobile-menu-head{display:flex;align-items:center;justify-content:space-between}.mobile-menu-links{display:grid;gap:8px;margin-top:38px}.mobile-menu-links a{padding:15px 0;border-bottom:1px solid rgba(255,255,255,.1);font-family:"Fraunces",serif;font-size:27px}
