<script>(()=>{'use strict';const $=(s,c=document)=>c.querySelector(s),$$=(s,c=document)=>[...c.querySelectorAll(s)],body=document.body,menu=$('#mobileMenu'),toast=$('#toast');let activeFilter='all',selected=[];const showToast=m=>{toast.textContent=m;toast.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>toast.classList.remove('show'),2600)};const openModal=m=>{m?.classList.add('open');m?.setAttribute('aria-hidden','false');body.style.overflow='hidden'};const closeModal=m=>{m?.classList.remove('open');m?.setAttribute('aria-hidden','true');body.style.overflow=''};$('#menuOpen')?.addEventListener('click',()=>{menu.classList.add('open');menu.setAttribute('aria-hidden','false');body.style.overflow='hidden'});$('#menuClose')?.addEventListener('click',()=>{menu.classList.remove('open');menu.setAttribute('aria-hidden','true');body.style.overflow=''});$$('[data-close-modal]').forEach(b=>b.addEventListener('click',()=>closeModal(b.closest('.modal'))));$$('.modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)closeModal(m)}));document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.classList.remove('open');body.style.overflow='';$$('.modal.open').forEach(closeModal)}});const cards=()=>$$('[data-card]');const applyFilters=()=>{const q=($('#favoriteSearch')?.value||'').trim().toLowerCase();let visible=0;cards().forEach(card=>{const matchesFilter=activeFilter==='all'||(card.dataset.category||'').includes(activeFilter);const matchesSearch=!q||(card.dataset.search||'').includes(q);const show=matchesFilter&&matchesSearch;card.hidden=!show;if(show)visible++});$('#emptyState')?.classList.toggle('visible',visible===0)};$$('.tab').forEach(t=>t.addEventListener('click',()=>{$$('.tab').forEach(x=>x.classList.remove('active'));t.classList.add('active');activeFilter=t.dataset.filter;applyFilters()}));$$('[data-collection-filter]').forEach(c=>c.addEventListener('click',()=>{$$('[data-collection-filter]').forEach(x=>x.classList.remove('active'));c.classList.add('active');activeFilter=c.dataset.collectionFilter;$$('.tab').forEach(x=>x.classList.toggle('active',x.dataset.filter===activeFilter));applyFilters()}));$('#favoriteSearch')?.addEventListener('input',applyFilters);const updateCount=()=>{$('#savedCount').textContent=cards().filter(c=>!c.hidden).length};$$('[data-remove]').forEach(b=>b.addEventListener('click',()=>{const card=b.closest('[data-card]');card.animate([{opacity:1,transform:'scale(1)'},{opacity:0,transform:'scale(.96)'}],{duration:220,easing:'ease',fill:'forwards'}).finished.then(()=>{card.remove();selected=selected.filter(i=>i.input!==card.querySelector('[data-select]'));updatePlan();updateCount();applyFilters()});showToast('Experiența a fost eliminată din favorite.')}));const collectionModal=$('#collectionModal'),alertModal=$('#alertModal'),itineraryModal=$('#itineraryModal');$('#createCollection')?.addEventListener('click',()=>openModal(collectionModal));$('#createCollectionTop')?.addEventListener('click',()=>openModal(collectionModal));$('#collectionForm')?.addEventListener('submit',e=>{e.preventDefault();const name=$('#collectionName').value.trim();if(!name)return;closeModal(collectionModal);e.target.reset();showToast(`Colecția „${name}” a fost creată.`)});$$('[data-collection]').forEach(b=>b.addEventListener('click',()=>showToast(`${b.dataset.name} a fost adăugată în „Weekend cu familia”.`)));$$('[data-alert]').forEach(b=>b.addEventListener('click',()=>{$('#alertTitle').textContent=`Alertă pentru ${b.dataset.name}`;openModal(alertModal)}));$('#manageAlerts')?.addEventListener('click',()=>{$('#alertTitle').textContent='Gestionează alertele';openModal(alertModal)});$('#alertForm')?.addEventListener('submit',e=>{e.preventDefault();closeModal(alertModal);showToast('Alerta de disponibilitate a fost salvată.');});$('#notificationButton')?.addEventListener('click',()=>showToast('Ai 2 alerte active în Lista mea.'));$('#selectHint')?.addEventListener('click',()=>showToast('Bifează 2–3 carduri folosind butonul din colțul imaginii.'));const updatePlan=()=>{selected=$$('[data-select]:checked').map(input=>({input,name:input.dataset.name,time:input.dataset.time,duration:input.dataset.duration,image:input.dataset.image}));if(selected.length>3){const last=selected.pop();last.input.checked=false;showToast('Poți selecta maximum 3 experiențe.')}$('#planCount').textContent=`${selected.length} ${selected.length===1?'experiență selectată':'experiențe selectate'}`;$('#planBar').classList.toggle('visible',selected.length>0);$('#planChips').innerHTML=selected.map(i=>`<img class="plan-chip" src="${i.image}" alt="${i.name}">`).join('')};$$('[data-select]').forEach(i=>i.addEventListener('change',updatePlan));$('#buildPlan')?.addEventListener('click',()=>{if(selected.length<2){showToast('Selectează cel puțin 2 experiențe.');return}const sorted=[...selected].sort((a,b)=>a.time.localeCompare(b.time));$('#itineraryList').innerHTML=sorted.map((i,index)=>`<article class="itinerary-item"><time>${i.time}</time><span><strong>${i.name}</strong><span>${i.duration}${index<sorted.length-1?' · 25 min deplasare către următoarea zonă':''}</span></span></article>`).join('');openModal(itineraryModal)});if(!matchMedia('(prefers-reduced-motion: reduce)').matches){$$('.hero-copy > *').forEach((el,i)=>el.animate([{opacity:0,transform:'translateY(20px)'},{opacity:1,transform:'translateY(0)'}],{duration:560,delay:50+i*65,easing:'cubic-bezier(.22,.8,.2,1)',fill:'both'}));const route=$('#heroRoute');if(route){const l=route.getTotalLength();route.style.strokeDasharray=l;route.style.strokeDashoffset=l;route.animate([{strokeDashoffset:l},{strokeDashoffset:0}],{duration:1700,delay:240,easing:'cubic-bezier(.22,.8,.2,1)',fill:'forwards'})}$$('.saved-mini').forEach((el,i)=>el.animate([{opacity:0,transform:'translateY(18px) rotate(0deg)'},{opacity:1,transform:getComputedStyle(el).transform}],{duration:650,delay:220+i*90,easing:'cubic-bezier(.22,.8,.2,1)',fill:'both'}));const o=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.animate([{opacity:0,transform:'translateY(14px)'},{opacity:1,transform:'translateY(0)'}],{duration:460,easing:'cubic-bezier(.22,.8,.2,1)',fill:'both'});o.unobserve(e.target)}}),{threshold:.08});$$('.feature,.adventure-card,.aside-card,.suggestion').forEach(el=>o.observe(el))}applyFilters();updateCount()})();</script>
<script>
(function(){
  function nvAuth(){ try { return JSON.parse(localStorage.getItem('nordvale_auth')||'null'); } catch(e){ return null; } }
  var a = nvAuth();
  if(!a || !a.token){ location.href='/autentificare?next='+encodeURIComponent(location.pathname+location.search); return; }
  var AH = { 'Authorization':'Bearer '+a.token };
  function api(ac,opt){ opt=opt||{}; opt.headers=Object.assign({},AH,opt.headers||{}); return fetch('/api/proxy.php?action='+ac,opt).then(function(r){return r.json().catch(function(){return{};});}).catch(function(){return{};}); }
  function post(ac,b){ return api(ac,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b||{})}); }
  function esc(s){ var d=document.createElement('div'); d.textContent=(s==null?'':String(s)); return d.innerHTML; }
  function initials(n){ n=(n||'').trim(); if(!n)return 'N'; var p=n.split(/\s+/); return (((p[0]||'')[0]||'')+((p[1]||'')[0]||'')).toUpperCase()||'N'; }
  function hydrateUser(u){ if(!u)return; var name=u.name||(((u.first_name||'')+' '+(u.last_name||'')).trim())||'Cont Nordvale'; window.__nvName=name; var box=document.querySelector('.profile-mini'); if(box){ var av=box.querySelector('.avatar'); if(av)av.textContent=initials(name); var st=box.querySelector('strong'); if(st)st.textContent=name; var em=box.querySelector('strong + span'); if(em&&u.email)em.textContent=u.email; } }
  document.querySelectorAll('a,button').forEach(function(el){ if((el.textContent||'').trim()==='Deconectare'){ el.addEventListener('click',function(ev){ ev.preventDefault(); post('logout').finally(function(){ localStorage.removeItem('nordvale_auth'); location.href='/'; }); }); } });
  hydrateUser(a.user);
  api('me').then(function(d){ if(d&&d.success&&d.data){ a.user=Object.assign({},a.user,d.data); try{localStorage.setItem('nordvale_auth',JSON.stringify(a));}catch(e){} hydrateUser(a.user); } });

  api('acc-favorites').then(function(d){ if(!(d&&d.success&&d.data))return; var evs=d.data.events||[]; var arts=d.data.artists||[]; var items=evs.concat(arts); var grid=document.querySelector('#adventureGrid'); if(!grid||!items.length)return;
    grid.innerHTML=items.map(function(it){ var title=it.title||('#'+it.item_id); var cat=(it.category||'').toLowerCase(); var img=it.image||it.poster||it.image_url||'';
      return '<article class="adventure-card" data-card data-category="'+esc(cat)+'" data-search="'+esc((title+' '+(it.category||'')).toLowerCase())+'">'
       +'<div class="card-media" style="min-height:180px;background:var(--pine-800)">'+(img?('<img alt="'+esc(title)+'" src="'+esc(img)+'">'):'')
       +'<button aria-label="Elimină din favorite" class="heart" data-nv-remove data-item-type="'+esc(it.item_type)+'" data-item-id="'+esc(it.item_id)+'" type="button"><svg fill="currentColor" height="18" viewbox="0 0 24 24" width="18"><path d="M12 20s-7-4.6-7-10a4 4 0 0 1 7-2.6A4 4 0 0 1 19 10c0 5.4-7 10-7 10Z"></path></svg></button>'
       +(it.category?('<span class="card-tags"><span class="tag">'+esc(it.category)+'</span></span>'):'')+'</div>'
       +'<div class="card-body"><div class="card-top"><span><h3>'+esc(title)+'</h3><p>'+esc(it.item_type==='artist'?'Artist salvat':'Experiență salvată')+'</p></span></div>'
       +'<div class="card-actions"><a class="btn btn-dark" href="'+(it.slug?('/experienta/'+esc(it.slug)):'/experiente')+'">Vezi</a></div></div></article>'; }).join('');
    var sc=document.querySelector('#savedCount'); if(sc)sc.textContent=items.length;
    grid.querySelectorAll('[data-nv-remove]').forEach(function(b){ b.addEventListener('click',function(){ var card=b.closest('[data-card]'); b.disabled=true; post('acc-fav-toggle',{item_type:b.dataset.itemType,item_id:parseInt(b.dataset.itemId,10),meta:{}}).finally(function(){ if(card)card.remove(); if(sc)sc.textContent=grid.querySelectorAll('[data-card]').length; }); }); });
  });
})();
</script>
